class Box:
    def __init__(self):
        self.__length = 0.0
        self.__breadth = 0.0
        self.__height = 0.0

    def setDimensions(self, l, b=None, h=None):
        if b is None and h is None:
            self.__length = l
            self.__breadth = l
            self.__height = l
        else:
            self.__length = l
            self.__breadth = b
            self.__height = h

    def calculateVolume(self):
        return self.__length * self.__breadth * self.__height

def compareBoxes(b1, b2):
    v1 = b1.calculateVolume()
    v2 = b2.calculateVolume()
    if v1 > v2:
        print("Box 1 is larger")
    elif v2 > v1:
        print("Box 2 is larger")
    else:
        print("Both boxes are equal in volume")

def main():
    import sys
    data1 = list(map(int, sys.stdin.readline().split()))
    data2 = list(map(int, sys.stdin.readline().split()))

    box1 = Box()
    if data1[0] == 1:
        box1.setDimensions(data1[1], data1[2], data1[3])

    box2 = Box()
    if data2[0] == 1:
        box2.setDimensions(data2[1], data2[2], data2[3])
    elif data2[0] == 2:
        box2.setDimensions(data2[1])

    vol1 = box1.calculateVolume()
    vol2 = box2.calculateVolume()

    print(f"Volume of Box 1: {vol1:.2f}")
    print(f"Volume of Box 2: {vol2:.2f}")
    compareBoxes(box1, box2)

if __name__ == "__main__":
    main()
